"""builds boxes/inject_aw_eval.py = a new docstring + inject_st_eval.py (body) copied with explicit edits (each asserted to apply exactly once) + the §234 parts
(scratch/s234_build/inject_aw_eval_parts.py, inserted before load())."""
src = open("boxes/inject_st_eval.py", encoding="utf-8").read()
body = src[src.index("import argparse\n"):]
DOC = '''"""THEORY §234 ANSWER-WRITE evaluation (AW_v1 §3 / AW_draft §3) for boxes/inject_aw.py runs = inject_st_eval's parts on the run's own AW inputs (tok_aw: every
pass input + " The answer is:"; CUE-ONLY / CUE-WRONG inputs + the same suffix) + four §234 parts. fp32; per-item outputs stored. Generated by
scratch/s234_build/mk_inject_aw_eval.py (inject_st_eval.py stays byte-identical). For --write_src all runs it is inject_st_eval (minus probe / ws).
  acc / lp5 / mean_s / cue_only / cue_wrong   as inject_st_eval (CUE-ONLY pass input = [EOT] + enc(" " + cue_t) + SFX; CUE-WRONG input + SFX).
  swap_k     SWAP-K (binding STATE-USE b): 1,000 same-skeleton d 2 pairs (aw_checks PAIRS law): recipient's S_K := donor's S_K, decoder on the recipient's
             text; follow_U (U = {donor final, cf_a(1)}), floor (MEAN-K: the donors' mean S_K), per pair.
  swap_1     SWAP-1 (descriptive): S_1 := donor's S_1, passes 2..K' own; follow cf_a(1) at K' 2 and K.
  probe      end-of-run u1|v1 / read1|v1 / l0|v1 probes, pass-1 trunk argmax, pass-1 / pass-2 key cosine (write_src answer only).
  ws         WS-READOUT on all of TEST2 d 1..d_max per pass (write_src answer only; Note 234-5 c; CHAIN at P-4 = every pass 2..d on d 3-4 >= 0.50).
  lp5h       (P-4, Note 234-5 a) LP5-4 MEAN-AT-ceil(d/2) on TEST2 d 3..d_max: answers at K' = d (binding, pooled d 3-4) and think_k; per item.
  swap_kd    (P-4, Note 234-5 b + amendment, descriptive) d 3..d_max, 1,000 same-skeleton pairs per d (t = ceil(d/2); d 3 -> t 1): SWAP-K (S_K := donor's; U = {donor final, cf_a(t)};
             floor MEAN-K) and SWAP-MID (S_t := donor's, own later passes; U = {cf_a(t), cf_b(t)}; floor MEAN at t); per pair.
    python -m boxes.inject_aw_eval --run boxes/runs_fsq/<run> --parts acc,lp5,mean_s,cue_only,cue_wrong,swap_k,swap_1,probe,ws [--device cuda:0 --eval_bs 100]"""
'''
E = [
('from boxes import inject_st as ST  # noqa: E402\n',
 'from boxes import inject_st as ST  # noqa: E402\nfrom boxes import inject_aw as AW  # noqa: E402\nimport boxes.deltamem as DM  # noqa: E402\nimport boxes.ow_words as OW  # noqa: E402\n'),
('PARTS = ("acc", "lp5", "mean_s", "cue_only", "cue_wrong")', 'PARTS = ("acc", "lp5", "mean_s", "cue_only", "cue_wrong", "swap_k", "swap_1", "probe", "ws", "lp5h", "swap_kd", "opclass", "swap_prod", "lenstep")\nAW_ONLY = ("probe", "ws", "opclass", "lenstep")'),
('import json\n', 'import json\nimport math\n'),
('    return {d: [ST.tok_st(it, a.get("aux_target", "value"), a.get("cue", "none")) for it in sets[key][d]] for d in ds}',
 '    return {d: [AW.tok_aw(it, a.get("aux_target", "value"), a.get("cue", "none"), a.get("write_src", "all")) for it in sets[key][d]] for d in ds}'),
('        return [EOT] + IO.ENC.encode(" " + ST.cue_str(it["raw"], min(t, it["d"])))',
 '        return [EOT] + IO.ENC.encode(" " + ST.cue_str(it["raw"], min(t, it["d"]))) + (IO.SFX if a.get("write_src") == "answer" else [])   # §234: + the suffix'),
('                return [EOT] + IO.ENC.encode(" " + it["raw"]["text"] + " " + ST.cue_str(it["raw"], wrong_name(it, min(t, it["d"]))))',
 '                return [EOT] + IO.ENC.encode(" " + it["raw"]["text"] + " " + ST.cue_str(it["raw"], wrong_name(it, min(t, it["d"])))) + (IO.SFX if a.get("write_src") == "answer" else [])'),
('    ns = argparse.Namespace(**a); torch.manual_seed(a["seed"]); m, g, params = IO.build_model(ns, dev)',
 '    ns = argparse.Namespace(**{**a, "init_trunk": "", "init_sha": ""}); torch.manual_seed(a["seed"]); m, g, params = AW.build_aw(ns, dev)   # model.pt holds every weight'),
('    if m is None:\n        parts = [p_ for p_ in parts if p_ == "acc"]',
 '    if m is None:\n        parts = [p_ for p_ in parts if p_ == "acc"]\n    if a.get("write_src", "all") != "answer":\n        parts = [p_ for p_ in parts if p_ not in AW_ONLY]'),
('"cue": a.get("cue", "none"),\n            "think_k"', '"cue": a.get("cue", "none"), "write_src": a.get("write_src", "all"),\n            "think_k"'),
('              "cue_only": lambda: part_cue_only(m, g, sets, a, dev, bs, ds), "cue_wrong": lambda: part_cue_wrong(m, g, sets, a, dev, bs, ds)}[p_]()',
 '              "cue_only": lambda: part_cue_only(m, g, sets, a, dev, bs, ds), "cue_wrong": lambda: part_cue_wrong(m, g, sets, a, dev, bs, ds),\n'
 '              "swap_k": lambda: part_swap_k(m, g, sets, a, dev, bs), "swap_1": lambda: part_swap_1(m, g, sets, a, dev, bs), "probe": lambda: part_probe(m, g, sets, a, dev, bs),\n'
 '              "ws": lambda: part_ws(m, g, sets, a, dev, bs), "lp5h": lambda: part_lp5h(m, g, sets, a, dev, bs), "swap_kd": lambda: part_swap_kd(m, g, sets, a, dev, bs),\n'
 '              "opclass": lambda: part_opclass(m, g, sets, a, dev, bs), "swap_prod": lambda: part_swap_prod(m, g, sets, a, dev, bs),\n'
 '              "lenstep": lambda: part_lenstep(m, g, sets, a, dev, bs)}[p_]()'),   # §241 LEN-STEP
('        assert a.get(k_) in (None, v_), ("§233: set sha mismatch vs args.json", k_)', '        assert a.get(k_) in (None, v_), ("§234: set sha mismatch vs args.json", k_)'),
('    if sets is None:\n        sets = IO.build_sets()', '    if sets is None:\n        sets = IO.build_sets(mul_s_p=law(a))   # §236 / §238: the run\'s law (law() raises on unknown values)'),
# §239 LONG-RUN: the --kprime_list CLI option (default '' = the unchanged run() path) -> run_long (eval_long.json only)
('    a = ap.parse_args(); run(a.run, [p_ for p_ in a.parts.split(",") if p_], a.device, a.eval_bs); print("DONE", a.run, flush=True)',
 '    ap.add_argument("--kprime_list", default="", help="§239: e.g. 8,16,32,64 -> eval_long.json only (run_long); default empty = the parts path")\n'
 '    ap.add_argument("--long_ds", default="2,3,4,5", help="§239: the d values of run_long")\n'
 '    ap.add_argument("--long_name", default="eval_long.json", help="§240: the run_long output file (e.g. eval_long_k128.json)")\n'
 '    a = ap.parse_args()\n'
 '    if a.kprime_list:\n'
 '        run_long(a.run, a.device, a.eval_bs, [int(x) for x in a.kprime_list.split(",")], [int(x) for x in a.long_ds.split(",")], a.long_name); return\n'
 '    run(a.run, [p_ for p_ in a.parts.split(",") if p_], a.device, a.eval_bs); print("DONE", a.run, flush=True)'),
]
for o, n in E:
    assert body.count(o) == 1, ("edit not applied exactly once", body.count(o), o[:90]); body = body.replace(o, n)
parts = open("scratch/s234_build/inject_aw_eval_parts.py", encoding="utf-8").read()
i = body.index("def load(run, dev):"); body = body[:i] + parts + body[i:]
assert "ST.tok_st(" not in body and "IO.build_model(" not in body, "leftovers"
open("boxes/inject_aw_eval.py", "w", encoding="utf-8", newline="\n").write(DOC + body)
print("written", len(E), "edits")
